# -*- coding: utf-8 -*-
"""Kaggle実機サンプル用の長文架空相談（天文同好会の企画運営）。

相談正本は `kaggle/people_sample.csv` の consultation 列。CSVとの一致・字数・
サニタイズ・プロンプト到達は tests で固定する。元の話題（仕事・介護・進路）と
異なる地域文化活動／市民科学イベントの企画運営を題材にする。
"""
from __future__ import annotations
import csv
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
CSV_PATH = ROOT / "kaggle" / "people_sample.csv"
SAMPLE_ROW_INDEX = 0
TARGET_CHARS = 1600
TOLERANCE = 160
CONSULTATION = '架空の検証用相談です（実在の人物ではありません）。私は三十代半ばで、地域の小さな天文同好会の運営を手伝っています。会員は大人が中心ですが、近所の子どもたちにも星空を楽しんでもらえるよう、月に一度、公民館の屋上で観望会を開いてきました。昨年までは市の施設を借りられましたが、改修工事で夜間利用が難しくなり、活動の場所を探し直すことになりました。候補は郊外の学校のグラウンド、海沿いの広場、商店街の屋上などです。望遠鏡を運びやすい場所は街灯が明るく、暗い空が見える場所は帰りの交通やトイレが心配です。会員の一人は山間部で大規模な観測会をしたいと言い、別の人は移動が難しい子どもや高齢者のために、街なかで短時間の催しを続けたいと考えています。私はどちらの意見も大切に思うため、決めきれずにいます。最近、自治体の市民活動助成に応募できると知りました。採択されれば携帯型の望遠鏡や赤色灯、簡易な案内板を用意できますが、申請書には年間計画や安全管理、参加者数の見込みを書く必要があります。私は機材の扱いには慣れていても、予算書や役割分担を整えるのは初めてです。締切まで二か月ほどしかなく、会員に声をかけても『あなたが詳しいから任せる』と言われ、いつの間にか準備の多くを一人で抱えてしまいました。交際相手の直人は同じ会の会員で、星図づくりや子ども向けの説明を一緒に担当しています。相手は計画を小さく始めて改善しようと言い、私は応募の機会を逃さず最初から複数会場で開催したいと思っています。意見が違っても活動そのものを大切にしたいのですが、準備の相談をすると、どちらが主導するかという話にすり替わることがあります。二人の相性（シナストリー）を占いの視点から眺めたうえで、共同運営の場で考えを伝え合う方法を知りたいです。観望会では、雲が出たときの代替プログラム、望遠鏡をのぞく順番、暗い場所での転倒防止、子どもの保護者への案内なども考えなくてはなりません。天候による中止をいつ決めるか、参加費を取るか、写真を撮るときの同意をどうするかも未整理です。専門家のように振る舞うのではなく、分からないことを確認しながら、安全で居心地のよい会にしたいと思っています。私は以前から、興味を持ったことを見つけると、細部まで準備してから人に見せようとする癖があります。そのため告知文が完成せず、参加者募集を始める時期が遅れがちです。会員からは『まず一回やってみよう』と言われますが、準備不足で誰かに迷惑をかけるのではないかと気になります。大きな企画にすることと、小さな試行を重ねることのどちらが今の活動に合うのか、占術ごとの違いも踏まえて考えたいです。仕事や家族の相談ではありませんが、余暇の活動にも時間と費用の限りがあります。平日の夜に準備を続けると睡眠が短くなり、趣味が義務のように感じる日もあります。助成金を得ること自体が目的になって、参加者の声を聞く余裕をなくすのは避けたいです。一方で、今の会員だけで活動を続けると、数年後に運営できる人がいなくなるのではという心配もあります。新しい人が自然に役割へ加われる仕組みを作るには、どこから手を付ければよいでしょうか。今年度中に申請するか、まず一つの会場で小規模な観望会を試し、来年度に助成を目指すかで迷っています。申し込む場合は、会場候補を一つに絞るべきか、複数の開催地を段階的に試す計画にするべきかも知りたいです。会のメンバーと相手にどの順番で相談すれば、意見の違いを対立ではなく企画の改善につなげられるでしょうか。星空の観察に向く時期や、準備を始める目安があれば、現実的な計画に落とし込む手掛かりにしたいです。最後に、私が見落としている強みや、抱え込みすぎている点があれば率直に教えてください。必ず成功する時期や、助成が通ると断言してほしいわけではありません。占いは考えを整理する一つの材料として使い、予算・安全・天候などは公的情報や関係者への確認を優先するつもりです。活動を続けるために今できる小さな一歩と、次の季節へ向けて手放してよい思い込みを知りたいです。'
CONSULTATION_ALT = '架空の検証用データです（実在の人物ではありません）。私は地域の天文同好会で、初心者向けの星空案内を続けています。今度、図書館の読書週間に合わせて「星を読む夜」という催しを提案しました。星座の物語を紹介するだけでなく、参加者が小さな星図を作り、実際の空で見つける体験を組み合わせたいと考えています。ところが、図書館側は静かな室内企画を希望し、同好会の仲間は望遠鏡を並べる屋外観望を中心にしたいと言います。場所も内容も一度に決めようとすると話がまとまらず、企画書の提出期限だけが近づいています。交際相手の直人も同じ会の運営に関わり、子ども向けの解説を担当しています。私は物語性を重視し、相手は天体の見え方を正確に伝えることを優先するため、準備の相談で細かな意見がぶつかることがあります。相性の見方も参考にしながら、共同で企画を作るときに互いの得意分野を活かす方法を知りたいです。参加者は小学生と保護者が中心になる見込みですが、夜の移動や天候の変化に配慮しなくてはなりません。屋外で星が見えない場合に備え、室内で月の満ち欠けを学ぶ工作や、星図を使ったゲームを用意する案も出ています。けれども、内容を増やしすぎると準備する人が疲れ、説明が駆け足になる心配があります。私は案内用の資料を何度も直し、専門用語をどこまで残すかで手が止まってしまいます。詳しい説明をすれば初心者には難しくなり、簡単にすると会の活動の魅力が伝わらないのではと考えてしまいます。会のメンバーには、まずは小さく開催して参加者の感想を聞こうという人もいれば、せっかくなら毎年続く大きな催しにしたいという人もいます。私は両方の期待に応えようとして、進行表や配布物まで自分で抱えがちです。以前の催しでは、担当を決めないまま当日を迎え、受付と説明を同時に行うことになりました。その反省から役割表を作ろうと思いますが、細かく決めすぎて自由な交流をなくすのも避けたいです。催しの成功だけでなく、参加した人が次も空を見上げたくなるような余韻を残したいと思っています。会場の予約、告知、申し込み受付、当日の安全確認をどの順番で進めればよいか、時期ごとの目安も知りたいです。予算は限られており、新しい機材を買うより、手持ちの双眼鏡や紙の星図を活用する案が現実的です。参加費を取る場合の説明や、写真を広報に使うときの確認方法も考えなくてはなりません。趣味の集まりを無理なく続けながら、初めて来る人にも入りやすい場にするため、今回の企画で何を優先し、どこを次回へ回すべきでしょうか。占いの示す流れは決定ではなく、話し合いの材料として受け止めたいです。相手や仲間にどのように提案すれば、意見の違いを対立ではなく改善につなげられるか、私自身が抱え込みすぎない工夫と一緒に助言をお願いします。次の催しでは、年齢や天文の経験に関係なく、参加者が一つでも自分で星を見つけたと思える時間を作りたいです。二人のシナストリーも、協働の相性を考える参考として知りたいです。当日のあとには、参加者が見つけた星や印象に残った説明を短く共有する時間も作りたいです。ただ、感想を求めすぎると自由に楽しめなくなるかもしれません。子どもが飽きたときに途中で帰れる案内や、天気が悪いときの連絡方法も、申込時に分かるようにしておきたいと思います。準備を完璧にするより、参加する人が安心して空を見上げられることを大切にしたいです。次の開催へつなぐ記録をどの程度残すべきか、運営の負担を増やさない方法も知りたいです。'

def is_fictional_consultation(text: str) -> bool:
    t = str(text or "")
    return (abs(len(t) - TARGET_CHARS) <= TOLERANCE
            and "架空" in t and "シナストリー" in t)

def load_sample_rows(csv_path: Path | None = None) -> list[dict]:
    with Path(csv_path or CSV_PATH).open(encoding="utf-8", newline="") as f:
        return list(csv.DictReader(f))

def csv_consultation(csv_path: Path | None = None) -> str:
    return str(load_sample_rows(csv_path)[SAMPLE_ROW_INDEX]["consultation"])
